def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 bg=max(set(x for r in grid for x in r),key=lambda x:sum(r.count(x) for r in grid))
 caps=[]; dots=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=bg:
    if grid[r][c] not in (1,2,4,8): pass
 # identify color that occurs as equal-length runs on opposite edges
 for color in set(sum(grid,[]))-{bg}:
  top=[c for c,x in enumerate(grid[0]) if x==color]; bot=[c for c,x in enumerate(grid[-1]) if x==color]
  left=[r for r in range(h) if grid[r][0]==color]; right=[r for r in range(h) if grid[r][-1]==color]
  if top and bot: caps=[('v',color,top,0),('v',color,bot,h-1)]; break
  if left and right: caps=[('h',color,left,0),('h',color,right,w-1)]; break
 dots=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg and not any((r==0 and c in a[2]) or (r==h-1 and c in a[2]) for a in caps)]
 dc=next((grid[r][c] for r,c in dots),1)
 for axis,color,indices,edge in caps:
  if axis=='v':
   for r in range(1,h-1):
    for c in indices: out[r][c]=dc
  else:
   for c in range(1,w-1):
    for r in indices: out[r][c]=dc
 for r,c in dots: out[r][c]=4
 return out
